+func TestBucketRefillsFractionally(t *testing.T) {
+	c := newClock()
+	b, err := ratelimit.NewBucket(4, 2, c.Now)
+	if err != nil {
+		t.Fatal(err)
+	}
+	if !b.Allow(4) {
+		t.Fatal("full bucket should allow capacity")
+	}
+	c.Advance(250 * time.Millisecond)
+	if got := b.Tokens(); math.Abs(got-0.5) > 1e-9 {
+		t.Fatalf("tokens = %v, want 0.5", got)
+	}
+	c.Advance(time.Hour)
+	if got := b.Tokens(); got != 4 {
+		t.Fatalf("tokens = %v, want capacity 4", got)
+	}
+}
+
+func TestBucketNoPartialConsume(t *testing.T) {
+	c := newClock()
+	b, _ := ratelimit.NewBucket(3, 1, c.Now)
+	if b.Allow(5) {
+		t.Fatal("n greater than capacity must be refused")
+	}
+	if b.Allow(0) || b.Allow(-1) || b.Allow(math.NaN()) {
+		t.Fatal("non-positive or NaN n must be refused")
+	}
+	if !b.Allow(2) {
+		t.Fatal("2 of 3 tokens should be allowed")
+	}
+	if b.Allow(2) {
+		t.Fatal("refused request must not take a partial amount")
+	}
+	if got := b.Tokens(); got != 1 {
+		t.Fatalf("tokens = %v, want 1", got)
+	}
+}
+
+func TestBucketClockBackwards(t *testing.T) {
+	c := newClock()
+	b, _ := ratelimit.NewBucket(2, 1, c.Now)
+	b.Allow(2)
+	c.Advance(-time.Second)
+	if got := b.Tokens(); got != 0 {
+		t.Fatalf("tokens = %v after clock went back, want 0", got)
+	}
+	c.Advance(2 * time.Second) // 1s past the latest seen time
+	if got := b.Tokens(); math.Abs(got-1) > 1e-9 {
+		t.Fatalf("tokens = %v, want 1", got)
+	}
+}
