+#[test]
+fn heavy_workload_runs_under_three_seconds() {
+    let mut set = IntervalSet::new();
+    let mut state = 12345u64;
+    let start = Instant::now();
+    for i in 0..300_000i64 {
+        let jitter = (lcg(&mut state) % 1000) as i64;
+        let base = 1_000_000_000 - i * 3000 - jitter;
+        let len = (lcg(&mut state) % 1001) as i64;
+        set.insert(c(base), c(base + len));
+        if i % 2 == 1 {
+            let x = (lcg(&mut state) % 1_000_000_001) as i64;
+            let rlen = (lcg(&mut state) % 1001) as i64;
+            set.remove(c(x), c(x + rlen));
+        }
+        let p = (lcg(&mut state) % 1_000_000_001) as f64;
+        let _ = set.contains(p);
+    }
+    let elapsed = start.elapsed();
+    assert!(!set.is_empty());
+    assert!(
+        elapsed.as_secs_f64() < 3.0,
+        "workload took {:?}",
+        elapsed
+    );
