+  expect(next("0 0 15W * *", "2024-06-01T00:00:00Z")).toBe("2024-06-14T00:00:00.000Z");
+  expect(next("0 0 15W * *", "2024-09-01T00:00:00Z")).toBe("2024-09-16T00:00:00.000Z");
+  expect(next("0 0 1W * *", "2024-05-31T00:00:00Z")).toBe("2024-06-03T00:00:00.000Z");
+  expect(next("0 0 31W * *", "2024-03-01T00:00:00Z")).toBe("2024-03-29T00:00:00.000Z");
+  expect(() => nextRun("0 0 31W 2 *", new Date("2024-02-01T00:00:00Z"))).toThrow(CronError);
+});
+
+test("dL is the last given weekday of the month", () => {
+  expect(next("0 0 * * 5L", "2024-01-01T00:00:00Z")).toBe("2024-01-26T00:00:00.000Z");
+  expect(next("0 0 * * friL", "2024-01-01T00:00:00Z")).toBe("2024-01-26T00:00:00.000Z");
+  expect(() => nextRun("0 0 * * 5W", new Date(0))).toThrow(CronError);
+});
+
+test("d#k is the k-th weekday of the month and skips months without it", () => {
+  expect(next("0 0 * * 5#3", "2024-01-01T00:00:00Z")).toBe("2024-01-19T00:00:00.000Z");
+  expect(next("0 0 * * FRI#3", "2024-01-01T00:00:00Z")).toBe("2024-01-19T00:00:00.000Z");
+  expect(next("0 0 * * 5#5", "2024-01-01T00:00:00Z")).toBe("2024-03-29T00:00:00.000Z");
+  expect(() => nextRun("0 0 * * 8#1", new Date(0))).toThrow(CronError);
+  expect(() => nextRun("0 0 * * 5#0", new Date(0))).toThrow(CronError);
+  expect(() => nextRun("0 0 * * 5#6", new Date(0))).toThrow(CronError);
+});
+
+test("specials can be mixed in a list", () => {
+  expect(next("0 0 * * 1#1,5L", "2024-01-01T00:00:00Z")).toBe("2024-01-26T00:00:00.000Z");
+});
+
+test("aliases are case-insensitive and reject extra text", () => {
+  expect(next("@daily", "2024-01-01T05:00:00Z")).toBe("2024-01-02T00:00:00.000Z");
+  expect(next("@HOURLY", "2024-01-01T05:30:00Z")).toBe("2024-01-01T06:00:00.000Z");
+  expect(next("@weekly", "2024-01-01T00:00:00Z")).toBe("2024-01-07T00:00:00.000Z");
+  expect(next("@monthly", "2024-01-15T00:00:00Z")).toBe("2024-02-01T00:00:00.000Z");
+  expect(next("@yearly", "2024-06-01T00:00:00Z")).toBe("2025-01-01T00:00:00.000Z");
+  expect(next("@ANNUALLY", "2024-06-01T00:00:00Z")).toBe("2025-01-01T00:00:00.000Z");
+  expect(() => nextRun("@daily extra", new Date(0))).toThrow(CronError);
+  expect(() => nextRun("@reboot", new Date(0))).toThrow(CronError);
+});
+
+test("invalid expressions throw CronError", () => {
+  const bad = [
+    "* * * *",
+    "* * * * * *",
+    "60 * * * *",
+    "* 24 * * *",
+    "* * 0 * *",
+    "* * 32 * *",
+    "* * * 0 *",
+    "* * * 13 *",
+    "* * * * 8",
+    "*/0 * * * *",
+    "5/15 * * * *",
+    "5-1 * * * *",
+    "1,,2 * * * *",
+    ",1 * * * *",
+    "MON * * * *",
+    "0 0 * * FOO",
+    "0 0 * FOO *",
+    "0 0 1L * *",
+    "0 0 W * *",
+    "0 0 * * L",
+    "0 0 * * W",
+    "0 0 * * 1-5#2",
+    "0 0 * * 5#",
+    "0 0 @ * *",
+  ];
+  for (const expr of bad) {
+    expect(() => nextRun(expr, new Date("2024-01-01T00:00:00Z"))).toThrow(CronError);
+  }
+  expect(new CronError("x")).toBeInstanceOf(Error);
+});
+
+test("throws CronError when no match exists within five years", () => {
+  expect(() => nextRun("0 0 30 2 *", new Date("2024-01-01T00:00:00Z"))).toThrow(CronError);
+});
+
+test("3000 calls over mixed rare schedules finish under 2 seconds", () => {
+  const schedules = ["0 0 29 2 1", "59 23 31 12 5L", "0 0 LW 2 *", "30 4 15W * 1#5", "0 0 29 2 *"];
+  const start = performance.now();
+  for (let i = 0; i < 3000; i++) {
+    const year = 2000 + (i % 100);
+    const month = i % 12;
+    const day = 1 + ((i * 7) % 28);
+    const d = new Date(Date.UTC(year, month, day, (i * 5) % 24, (i * 13) % 60));
+    try {
+      nextRun(schedules[i % 5], d);
+    } catch (e) {
+      if (!(e instanceof CronError)) throw e;
+    }
+  }
+  const elapsed = performance.now() - start;
+  expect(elapsed).toBeLessThan(2000);
+});

